    el('shopping-summary').textContent=rows.length+' matching priced markdown'+(rows.length===1?'':'s')+(feed.uniqloImport?' · UNIQLO imported '+stamp(feed.uniqloImport.importedAt)+(feed.uniqloImport.active?'':' · import expired; update UNIQLO'):'')+(filters.query?' · Search: '+filters.query:'')+(filters.maxPrice?' · item up to '+money(filters.maxPrice):'')+(filters.sort==='drop'?' · Biggest observed price drops first; listings without a drop follow.':filters.sort==='newest'?' · Newest first seen, not latest refresh.':'')+(filters.need===C.OPEN_NEEDS?' · All open needs: '+C.openNeeds(p).length:'')+(selected?' · Need: '+[selected.category!=='All'?selected.category:'',selected.garment,selected.use?selected.use+' (suggested use)':'',selected.material,selected.budget?'up to '+money(selected.budget):''].filter(Boolean).join(' · '):'');
    el('shopping-results').innerHTML=(rows.length?'<h3>'+({recommended:'Worth checking first',price:'Lowest item prices',newest:'Newest first seen',drop:'Biggest observed price drops'}[filters.sort])+'</h3><p class="flights-note shopping-caveat">Item prices only. QC delivery fee, final stock and returns need checking at the retailer.</p><details class="shopping-limits"><summary>Price, stock and sizing limits</summary><p class="flights-note">Voucher eligibility and exchanges need checking. Online stock does not confirm branch stock. Numeric clothing sizes need the retailer’s size chart; unchecked sizes remain visible unless you select confirmed sizes only.</p></details><div class="deal-grid">'+rows.slice(0,5).map(card).join('')+'</div>'+(rows.length>5?'<details><summary>Show '+(rows.length-5)+' more matching deals</summary><div class="deal-grid">'+rows.slice(5).map(card).join('')+'</div></details>':''):emptyResults(report,filters));
    var today=new Date(Date.now()+8*3600000).toISOString().slice(0,10),promos=(feed.promos || []).filter(function(i){return p.brands.includes(i.brand) && C.retailerOn(i,p) && C.brandMatch(i,filters.brand) && p.areas.includes(i.area) && i.branch && i.validTo>=today && (!i.validFrom || i.validFrom<=today) && C.safeUrl(i.url) && C.fresh(i,Date.now());}).sort(function(a,b){return C.AREAS.indexOf(a.area)-C.AREAS.indexOf(b.area);});
    el('shopping-stores').innerHTML='<h3>Store offers · QC first, then Ortigas, Makati and Pasay</h3>'+(promos.length?'<div class="deal-grid">'+promos.map(function(i){return '<article class="deal-card"><h3>'+esc(i.name)+'</h3><p>'+esc(i.branch)+' · '+esc(i.area)+'</p><p>Published valid until '+esc(i.validTo)+'</p><p class="flights-note">Sale announcement only; qualifying items, sizes and branch stock are unverified. Confirm conditions before travelling.</p>'+(i.terms?'<details><summary>Published conditions</summary><p class="flights-note">'+esc(i.terms)+'</p></details>':'')+link(i.url,'Read official terms')+'</article>';}).join('')+'</div>':'<p class="flights-note">No current, dated matching branch offer was verified by this run. Online prices are not a reason to travel to a branch.</p>')+'<p>'+link('https://www.smsupermalls.com/smdeals','SM promotions')+' · '+link('https://www.ayalamalls.com/promos-and-events','Ayala promotions · manual check')+'</p>';
    // One line per promotion: items sharing a retailer, brand and condition
    // ("Buy 3, Get 15% Off Curated · No min. spend.") are listed together.
    // Entries without a condition are the old per-card format; skip them.
    var groups=[];(feed.campaigns || []).filter(function(i){return i.condition && C.brandMatch(i,filters.brand) && C.safeUrl(i.url) && p.brands.includes(i.brand) && C.retailerOn(i,p) && (!i.validTo || i.validTo>=today) && (!i.validFrom || i.validFrom<=today) && C.fresh(i,Date.now());}).forEach(function(i){var key=[i.retailer,i.brand,i.kind,i.condition].join('|'),g=groups.find(function(x){return x.key===key;});if(!g)groups.push(g={key:key,rows:[]});g.rows.push(i);});
